#!/usr/bin/env python3
"""Static site builder. Run: python3 build.py -> dist/"""
import json,os,shutil,html
SITE="https://garettoswald9999.github.io/family-funding-tools"
NAME="Family Funding & Tools"
NL_URL="https://assets.mailerlite.com/jsonp/2720821/forms/201603881613920183/subscribe"
SB_URL="https://assets.mailerlite.com/jsonp/2720821/forms/201603907061810930/subscribe"
PRIV='<p class="priv">We only use your email to send these updates. Unsubscribe anytime.</p>'
def mlform(url,fid,btn,label="Email"):
    return f'<form class="nl-form ml-form" action="{url}" method="post"><label for="{fid}">{label}</label><input id="{fid}" type="email" name="fields[email]" required autocomplete="email" placeholder="you@example.com"><input type="hidden" name="ml-submit" value="1"><input type="hidden" name="anticsrf" value="true"><button type="submit" class="pill">{btn}</button><output aria-live="polite"></output></form>'+PRIV
E=html.escape
P=json.load(open('data/programs.json')); L=sorted(json.load(open('data/listings.json')),key=lambda l:not l.get('pinned'))
D='dist'; shutil.rmtree(D,ignore_errors=True); os.makedirs(D)
urls=[]
def page(path,title,desc,body,ld=None):
    depth=path.count('/'); r='../'*depth
    lds=''.join(f'<script type="application/ld+json">{json.dumps(x,ensure_ascii=False)}</script>' for x in (ld or []))
    nav=f'<a href="{r}funding/index.html">Funding Guide</a><a href="{r}directory/index.html">Directory</a><a href="{r}quiz.html">Quiz</a><a class="pill sm" href="{r}submit.html">Get Listed</a>'
    canon=SITE+'/'+path.replace('index.html','')
    h=f'''<!DOCTYPE html><html lang="en-CA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)}</title><meta name="description" content="{E(desc)}"><link rel="canonical" href="{canon}"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(desc)}"><meta property="og:type" content="website"><link rel="stylesheet" href="{r}style.css">{lds}</head><body><a class="skip" href="#main">Skip to content</a><header class="topnav"><div class="wrap"><a class="brand" href="{r}index.html">Family Funding &amp; Tools</a><nav aria-label="Main">{nav}</nav></div></header><main id="main">{body}</main><footer><div class="wrap"><section class="signup" id="newsletter" aria-labelledby="nl"><h2 id="nl">Weekly newsletter</h2><p>One short email a week. Free.</p>{mlform(NL_URL,'em-'+str(depth)+str(len(urls)),'Sign up')}</section><p class="disc">General info, not legal or financial advice. Always check the official link. <a href="{r}faq.html">FAQ</a> · <a href="{r}about.html">About</a> · <a href="{r}disclaimer.html">Disclaimer</a></p></div></footer><script src="{r}forms.js"></script></body></html>'''
    os.makedirs(os.path.dirname(os.path.join(D,path)) or D,exist_ok=True)
    open(os.path.join(D,path),'w').write(h); urls.append(canon)
def ul(xs): return '<ul>'+''.join(f'<li>{E(x)}</li>' for x in xs)+'</ul>'
# programs
cards=''
for p in P:
    links='<ul>'+''.join(f'<li><a href="{u}" rel="noopener">{E(t)}</a></li>' for t,u in p['links'])+'</ul>'
    b=f'<p class="crumb"><a href="index.html">Funding Guide</a></p><h1>{E(p["name"])}</h1><p class="gov">{E(p["gov"])}</p><h2>What it is</h2><p>{E(p["what"])}</p><h2>How much</h2><p>{E(p["amount"])}</p><h2>Who qualifies</h2>{ul(p["who"])}<h2>How to apply</h2><ol>'+''.join(f'<li>{E(s)}</li>' for s in p['steps'])+f'</ol><h2>Documents to gather</h2>{ul(p["docs"])}<h2>Official links</h2>{links}<p><a class="pill" href="../quiz.html">Take the eligibility quiz</a></p>'
    ld=[{"@context":"https://schema.org","@type":"HowTo","name":"How to apply for "+p['name'],"description":p['what'],"step":[{"@type":"HowToStep","position":i+1,"text":s} for i,s in enumerate(p['steps'])]}]
    page(f'funding/{p["slug"]}.html',f'{p["name"]}: BC parent guide',p['what'][:155],b,ld)
    cards+=f'<li class="card"><h3><a href="{p["slug"]}.html">{E(p["name"])}</a></h3><p>{E(p["what"][:140])}…</p></li>'
page('funding/index.html','Funding Guide for BC families of kids with disabilities','Plain-language guide to DTC, Child Disability Benefit, RDSP, BC Autism Funding, At Home Program, Jordan\'s Principle and more.',f'<div class="head"><h1>Funding Guide.</h1><p class="sub">Plain-language guides to the main programs for BC families raising a child with a disability. <a href="../quiz.html">Not sure where to start? Take the 2-minute quiz.</a></p></div><ul class="grid">{cards}</ul>')
# directory
cats=sorted({l['category'] for l in L}); regs=sorted({l['region'] for l in L})
def site_dd(l):
    x=''
    if l.get('status'): x+=f'<dt>Status</dt><dd><span class="badge">Coming soon</span> {E(l["status"])}</dd>'
    if l.get('owner_disclosure'): x+=f'<dt>Disclosure</dt><dd>{E(l["owner_disclosure"])}</dd>'
    u=l['url'] or l.get('app_store_url')
    x+=f'<dt>Official site</dt><dd><a href="{u}" rel="noopener nofollow">{E(u)}</a></dd>' if u else '<dt>App Store</dt><dd>Link coming at launch.</dd>'
    return x
def rel(l): return "This app is made by the founder of this site." if l.get('owner_disclosure') else "We don\'t sell this product and have no relationship with this organization."
for l in L:
    sbx=('<section class="feature sb-form" aria-label="Get notified"><h2>Get notified</h2>'+mlform(SB_URL,'sb-page','Get notified','Email me when Speakboard launches')+'</section>') if l['slug']=='speakboard' else ''
    b=f'<p class="crumb"><a href="index.html">Directory</a> › {E(l["category"])}</p><h1>{E(l["name"])}</h1><p>{E(l["description"])}</p><dl><dt>Category</dt><dd>{E(l["category"])}</dd><dt>Region</dt><dd>{E(l["region"])}</dd><dt>Price</dt><dd>{E(l["price"])}</dd><dt>Autism Funding eligible?</dt><dd>{E(l["funding_eligible"])}<br><small>{E(l["funding_note"])}</small></dd>{site_dd(l)}<dt>Last checked</dt><dd>{l["checked"]}</dd></dl><p class="note">{rel(l) if l.get("owner_disclosure") else rel(l)+' Prices and details: see the official site. <a href="../submit.html">Is this your listing?</a>'}</p>{sbx}'
    ld=[{"@context":"https://schema.org","@type":"Organization" if l['category'] in('Support groups & organizations','BC autism service providers') else "Product","name":l['name'],"description":l['description'],**({"url":l['url']} if l['url'] else {})}]
    page(f'directory/{l["slug"]}.html',f'{l["name"]}: {l["category"]}',l['description'][:155],b,ld)
badge=lambda l:' <span class="badge">Coming soon</span>' if l.get('status') else ''
disc=lambda l:'<p class="owner">'+E(l['owner_disclosure'])+'</p>' if l.get('owner_disclosure') else ''
fundtag=lambda l:'<span>May qualify for Autism Funding</span>' if l['funding_eligible'].startswith('Possibly') else ''
opt=lambda xs:''.join(f'<option>{E(x)}</option>' for x in xs)
items=''.join(f'<li class="card{' pinned' if l.get('pinned') else ''}" data-cat="{E(l["category"])}" data-reg="{E(l["region"])}" data-price="{l["price"]}" data-fund="{"y" if l["funding_eligible"].startswith("Possibly") else "n"}"><h3><a href="{l["slug"]}.html">{E(l["name"])}</a>{badge(l)}</h3><p>{E(l["description"])}</p>{disc(l)}<p class="tags"><span>{l["price"]}</span>{fundtag(l)}</p></li>' for l in L)
chiphtml=''.join(f'<button type="button" class="chip" data-cat="{E(c)}" aria-pressed="false">{E(c)}</button>' for c in cats)
dirb=f'''<div class="head"><h1>Directory.</h1><p class="sub">Tools and services for families. Tap a category.</p></div><div class="filters" role="search" aria-label="Filter listings"><div class="chips" role="group" aria-label="Category"><button type="button" class="chip" data-cat="" aria-pressed="true">All</button>{chiphtml}</div><label class="search">Search<input id="f-q" type="search" placeholder="Search tools"></label><details class="more"><summary>More filters</summary><div class="row"><label>Region<select id="f-reg"><option value="">All regions</option>{opt(regs)}</select></label><label>Price<select id="f-price"><option value="">Any price</option><option>Free</option><option>Paid</option><option>Varies</option></select></label><label class="check"><input type="checkbox" id="f-fund"> May qualify for Autism Funding</label></div></details></div><p id="count" aria-live="polite"></p><ul class="grid" id="list">{items}</ul><p class="note">“May qualify for Autism Funding” is our best reading of BC rules, not a promise. Check with the Autism Funding Branch first.</p><script src="../directory.js"></script>'''
page('directory/index.html','Canadian autism & special-needs tools directory','Directory of AAC apps, sensory and safety products, BC autism service providers and support groups, with Autism Funding notes.',dirb,[{"@context":"https://schema.org","@type":"ItemList","itemListElement":[{"@type":"ListItem","position":i+1,"name":l['name'],"url":f"{SITE}/directory/{l['slug']}.html"} for i,l in enumerate(L)]}])
json.dump(L,open(f'{D}/listings.json','w'),ensure_ascii=False)
# home
home=f'''<section class="hero"><h1>Help for your child.<br>Made simple.</h1><p class="sub">Funding, benefits and tools for Canadian families raising a child with a disability. Free. No login.</p><p><a class="pill lg" href="quiz.html">Find what your family qualifies for</a></p><p class="small"><a href="directory/index.html">Or browse {len(L)} tools and services ›</a></p></section><section class="feature" aria-labelledby="sb"><span class="badge">Coming soon</span><h2 id="sb">Speakboard — coming end of October</h2><p class="sub">An AAC app for iPhone and iPad, built by a BC dad for his non-verbal son. Made by the founder of this site.</p><div class="sb-form">{mlform(SB_URL,"sb-home","Get notified","Email me when Speakboard launches")}</div></section><section class="band"><div class="cards3"><a class="tile" href="funding/disability-tax-credit.html"><h2>Start with the DTC.</h2><p>One form that unlocks most other money.</p><span>Learn more ›</span></a><a class="tile" href="funding/autism-funding.html"><h2>Autism Funding is changing.</h2><p>It ends March 31, 2027. Here's what's next.</p><span>Learn more ›</span></a><a class="tile" href="funding/jordans-principle.html"><h2>Jordan's Principle.</h2><p>Support for First Nations kids, on or off reserve.</p><span>Learn more ›</span></a></div></section>'''
page('index.html',NAME+': BC disability funding guide & autism tools','Free plain-language guide and directory for Canadian (BC) parents of children with autism and disabilities: funding quiz, benefits checklists, AAC apps, sensory tools.',home,[{"@context":"https://schema.org","@type":"WebSite","name":NAME,"url":SITE}])
quiz='''<div class="head"><h1>What can you get?</h1><p class="sub">8 quick questions. Nothing leaves your device.</p></div><form id="quiz"><fieldset><legend>How old is your child?</legend><label><input type="radio" name="age" value="u6" required> Under 6</label><label><input type="radio" name="age" value="6to17"> 6–17</label><label><input type="radio" name="age" value="17h"> 17½ or older</label></fieldset><fieldset><legend>Does your child have an autism diagnosis?</legend><label><input type="radio" name="asd" value="y" required> Yes</label><label><input type="radio" name="asd" value="n"> No / not yet</label></fieldset><fieldset><legend>Is your child approved for the Disability Tax Credit (DTC)?</legend><label><input type="radio" name="dtc" value="y" required> Yes</label><label><input type="radio" name="dtc" value="n"> No</label><label><input type="radio" name="dtc" value="u"> Not sure</label></fieldset><fieldset><legend>Is your child First Nations?</legend><label><input type="radio" name="fn" value="y" required> Yes</label><label><input type="radio" name="fn" value="n"> No</label></fieldset><fieldset><legend>Do you live on reserve?</legend><label><input type="radio" name="res" value="y"> Yes</label><label><input type="radio" name="res" value="n" checked> No</label></fieldset><fieldset><legend>Is your family on BC income or disability assistance?</legend><label><input type="radio" name="ia" value="y" required> Yes</label><label><input type="radio" name="ia" value="n"> No</label></fieldset><fieldset><legend>Does your child need a lot of help with eating, dressing, toileting or washing?</legend><label><input type="radio" name="adl" value="y" required> Yes, with 3 or more</label><label><input type="radio" name="adl" value="n"> No / fewer</label></fieldset><fieldset><legend>Do you rent?</legend><label><input type="radio" name="rent" value="y" required> Yes</label><label><input type="radio" name="rent" value="n"> No</label></fieldset><button type="submit" class="pill">Show my checklist</button></form><section id="result" aria-live="polite" hidden><h2>Your checklist</h2><ol id="checklist"></ol><button type="button" class="pill ghost" onclick="window.print()">Print / save as PDF</button></section><script src="quiz.js"></script>'''
page('quiz.html','Free BC disability benefits eligibility quiz for parents','2-minute quiz that builds a personal checklist of BC and federal programs for your child with a disability.',quiz)
faqs=[("What should I apply for first?","Usually the Disability Tax Credit. Approval unlocks the Child Disability Benefit, RDSP grants and bonds, and BC's new disability supplement."),("Does autism qualify for the Disability Tax Credit?","It can. Approval depends on how severely the child is affected, as certified by a medical practitioner on Form T2201. A diagnosis alone doesn't guarantee it."),("Is BC Autism Funding ending?","Yes. It ends March 31, 2027, and is being replaced by the needs-based BC Children and Youth Disability Benefit ($6,500 or up to $17,000/year) and an income-tested supplement (up to $6,000/year). New Autism Funding applications are open until March 2027."),("Can I get the RDSP bond if I'm on assistance?","The bond needs no contribution and is based on family income; for 2026 the full $1,000 is paid if adjusted family net income is $38,237 or less. In BC, RDSPs are exempt assets for assistance; confirm with the ministry."),("Can I get BC Housing RAP while on income assistance?","Generally no, because both are shelter subsidies. The exception is Medical Services Only."),("Is Jordan's Principle only for kids on reserve?","No. It covers First Nations children on and off reserve. Call 1-855-572-4453, 24/7."),("Do I have to file taxes if I have no income?","Yes. CCB, CDB, BC Family Benefit and RDSP bond all depend on filing every year."),("Are listings in the directory endorsements?","No. Listings are information only. We check that each official website works but don't test products.")]
fb=''.join(f'<h2>{E(q)}</h2><p>{E(a)}</p>' for q,a in faqs)
page('faq.html','FAQ: disability benefits & autism funding in BC','Answers to common questions from BC parents about DTC, autism funding changes, RDSP, Jordan\'s Principle and housing.',f'<h1>Frequently asked questions</h1>{fb}',[{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":q,"acceptedAnswer":{"@type":"Answer","text":a}} for q,a in faqs]}])
page('about.html','About','Built by a Chilliwack BC parent with lived experience.','<h1>About</h1><p class="draft">[DRAFT, waiting for Garett\'s approval]</p><p>Hi, I\'m Garett, a dad in Chilliwack, BC. My son is autistic and non-verbal. I\'ve spent years working through forms, phone lines and waitlists, and I built this so other parents don\'t have to start from zero. [Garett: add your story in your own words.]</p><p>Find me on X: <a href="https://x.com/Gcarsona99">@Gcarsona99</a>.</p><p>This site is independent and isn\'t connected to any government.</p>')
page('disclaimer.html','Disclaimer','Not legal, medical or financial advice.','<h1>Disclaimer</h1><p>This site gives general, plain-language information. It is not legal, medical, tax or financial advice, and it is not a government website. Programs and amounts change; always check the official source linked on each page. Directory listings are not endorsements. The quiz runs only in your browser and stores nothing.</p>')
sub='''<h1>Submit or feature your listing</h1><p>Make AAC apps, sensory or safety products, or run a BC service or support group? Get listed.</p><table><caption>Draft pricing (coming soon; payments are not on yet)</caption><thead><tr><th scope="col">Tier</th><th scope="col">Price</th><th scope="col">Includes</th></tr></thead><tbody><tr><td>Basic</td><td>Free</td><td>Standard listing after review</td></tr><tr><td>Featured</td><td>$49–149/mo (draft)</td><td>Top of category, badge, logo. Marked “Sponsored”</td></tr><tr><td>Newsletter sponsor</td><td>TBD (draft)</td><td>One clearly labelled sponsor spot per weekly issue</td></tr></tbody></table><p>Paid placement never changes our funding information, and every paid listing is clearly labelled.</p><h2>Submission form (coming soon)</h2><form onsubmit="event.preventDefault();this.querySelector('output').textContent='Thanks! Submissions open soon (not connected yet).'"><label>Organization / product name<input type="text" name="name" required></label><label>Official website<input name="url" type="url" required></label><label>Category<select name="cat"><option>AAC apps &amp; devices</option><option>Communication help (free)</option><option>Sensory products</option><option>Safety products</option><option>BC autism service providers</option><option>Support groups &amp; organizations</option></select></label><label>Region<input type="text" name="region"></label><label>Contact email<input name="email" type="email" required></label><label>Short description<textarea name="desc" maxlength="300"></textarea></label><button type="submit" class="pill">Submit</button><output aria-live="polite"></output></form>'''
page('submit.html','Submit or feature your listing','List your autism or special-needs tool or service for Canadian families.',sub)
for f in ['style.css','quiz.js','directory.js','forms.js']: shutil.copy('src/'+f,D)
open(f'{D}/.nojekyll','w').write('')
open(f'{D}/robots.txt','w').write(f'User-agent: *\nAllow: /\n\nSitemap: {SITE}/sitemap.xml\n')
open(f'{D}/sitemap.xml','w').write('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{u}</loc><lastmod>2026-10-14</lastmod></url>' for u in urls)+'</urlset>\n')
llms=f'# {NAME}\n\n> Free plain-language guide for Canadian (starting with BC) parents of children with autism and other disabilities: funding programs, eligibility quiz, and a directory of AAC, sensory, safety tools and BC services. Amounts verified against official sources on 2026-10-14. Not legal advice.\n\n## Funding Guide\n'+''.join(f'- [{p["name"]}]({SITE}/funding/{p["slug"]}.html): {p["amount"]}\n' for p in P)+'\n## Pages\n- [Eligibility quiz]('+SITE+'/quiz.html)\n- [FAQ]('+SITE+'/faq.html)\n- [Directory]('+SITE+'/directory/index.html), machine-readable: '+SITE+'/listings.json\n\n## Directory\n'+''.join(f'- [{l["name"]}]({SITE}/directory/{l["slug"]}.html): {l["category"]}; {l["region"]}; {l["description"]}\n' for l in L)
open(f'{D}/llms.txt','w').write(llms)
print(len(urls),'pages')
